INSERT INTO scholarship (name, provider, description, amount, application_url, min_age, max_age, required_gender, eligible_region, required_military_status, max_income_bracket, min_gpa, min_gpa_basis, requires_disability, foreigner_eligibility, grade_level, major, affiliated_institution, min_credits, admission_score_condition, headcount, application_period, eligible_university, eligible_college, required_enrollment_status, min_grade, max_grade, required_degree_level, category_l1, category_l2) VALUES
('서울인재대학장학금', '서울미래인재재단', '서울 소재 대학 재학 또는 서울시민의 자녀로 비서울 소재 대학 재학 중인 2학년 이상 학생 대상. 기초생활수급자/차상위/학자금지원 4구간 이하, 전체학기 평점 백분위 90점 이상(4.5만점 GPA 아님, 백분위 성적 기준이라 min_gpa로 환산 불가). 연 200만원 1회 지급.', 2000000, 'https://www.seoulfuture.or.kr', NULL, NULL, NULL, '서울', NULL, 4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '전체학기 평점 백분위 90점 이상(백분위 기준, GPA 아님)', NULL, '2026.8.3~8.10', NULL, NULL, NULL, 2, NULL, NULL, 'school_external', 'local_gov'),
('대학(원)생 학자금대출 이자지원(울산)', '울산광역시', '주민등록상 주소지가 울산인 대학(원) 재학생·휴학생 대상. 2017년 이후 한국장학재단 학자금대출 이자(2026년 1~6월분) 전액 지원.', NULL, 'https://www.ulsan.go.kr', NULL, NULL, NULL, '울산', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026.7.31~8.30', NULL, NULL, NULL, NULL, NULL, NULL, 'support_fund', 'youth_living_support');
